<?php
declare(strict_types=1);
require_once __DIR__.'/planning_engine.php';require_once __DIR__.'/platform.php';require_once __DIR__.'/bank_formats.php';
function financeCents(string $raw,string $locale='iso'):int {
 $raw=trim($raw);if($locale==='de'){if(!preg_match('/^[+-]?(?:\d{1,9}|\d{1,3}(?:\.\d{3}){1,2})(?:,\d{1,2})?$/D',$raw))throw new InvalidArgumentException('Deutscher Betrag ungültig.');$raw=str_replace(['.',','],['','.'],$raw);}elseif($locale!=='iso')throw new InvalidArgumentException('Zahlenformat unbekannt.');
 if(!preg_match('/^([+-]?)(\d{1,9})(?:\.(\d{1,2}))?$/D',$raw,$m))throw new InvalidArgumentException('Betrag benötigt maximal zwei Dezimalstellen.');$value=(int)$m[2]*100+(int)str_pad($m[3]??'',2,'0');return ($m[1]==='-'?-1:1)*$value;
}
function financeDecimal(int $cents):string{return ($cents<0?'-':'').intdiv(abs($cents),100).'.'.str_pad((string)(abs($cents)%100),2,'0',STR_PAD_LEFT);}
function financeTax(int $gross,int $rate):int {if(!in_array($rate,[0,7,19],true)||$gross<0)throw new InvalidArgumentException('Steuersatz/Betrag erfordert Fachprüfung.');return intdiv($gross*$rate+intdiv(100+$rate,2),100+$rate);}
interface GszReadOnlyBankAdapter {public function transactions(string $from,string $to):array;public function balance():array;}
final class GszDisconnectedBank implements GszReadOnlyBankAdapter {public function transactions(string $from,string $to):array{throw new RuntimeException('Onlinebanking nicht verbunden. Nur manueller Import.');}public function balance():array{throw new RuntimeException('Kein online abgerufener Kontostand.');}}
function bankParseCsv(string $raw,array $map,string $locale='de',string $delimiter=';',int $maxRows=1000):array {
 if(strlen($raw)>2*1024*1024||!mb_check_encoding($raw,'UTF-8')||str_contains($raw,"\0"))throw new InvalidArgumentException('Bankimport: UTF-8, maximal 2 MB, keine Nullbytes.');if(!in_array($delimiter,[';',','],true))throw new InvalidArgumentException('Trennzeichen ungültig.');$raw=preg_replace('/^\xEF\xBB\xBF/','',$raw);$f=fopen('php://temp','w+');fwrite($f,$raw);rewind($f);$header=fgetcsv($f,16384,$delimiter,'"','');if(!$header||count($header)!==count(array_unique($header)))throw new InvalidArgumentException('Bank-CSV benötigt eindeutige Kopfzeile.');foreach(['booked_on','amount','currency','purpose','counterparty','id'] as $key)if(empty($map[$key])||!in_array($map[$key],$header,true))throw new InvalidArgumentException('CSV-Zuordnung fehlt: '.$key);
 $out=[];$ids=[];while(($row=fgetcsv($f,16384,$delimiter,'"',''))!==false){if($row===[null])continue;if(count($row)!==count($header))throw new InvalidArgumentException('CSV-Spaltenzahl abweichend.');$r=array_combine($header,$row);$id=trim($r[$map['id']]);$date=trim($r[$map['booked_on']]);$value=!empty($map['value_on'])?trim($r[$map['value_on']]??''):$date;$currency=trim($r[$map['currency']]);$purpose=trim($r[$map['purpose']]);$counterparty=trim($r[$map['counterparty']]);if($id===''||mb_strlen($id)>190||!zgsValidDate($date)||!zgsValidDate($value)||$currency!=='EUR'||mb_strlen($purpose)>2000||mb_strlen($counterparty)>500)throw new InvalidArgumentException('Bankzeile: stabile ID, ISO-Datum, EUR und Textgrenzen prüfen.');$amount=financeCents($r[$map['amount']],$locale);$item=['external_id'=>$id,'booked_on'=>$date,'value_on'=>$value,'amount_cents'=>$amount,'currency'=>$currency,'purpose'=>$purpose,'counterparty'=>$counterparty];$hash=hash('sha256',json_encode($item,JSON_THROW_ON_ERROR));if(isset($ids[$id])&&$ids[$id]!==$hash)throw new RuntimeException('Gleiche Quellen-ID mit abweichenden Werten.');$ids[$id]=$hash;$item['source_key']=hash('sha256',$id);$item['record_hash']=$hash;$out[$id]=$item;if(count($out)>max(1,min(5000,$maxRows)))throw new RuntimeException('Bankimport-Zeilenlimit.');}fclose($f);if(!$out)throw new InvalidArgumentException('Keine Bankumsätze.');return array_values($out);
}
function bankPreview(PDO $pdo,int $admin,int $account,string $raw,array $map,string $locale,string $delimiter,int $limit=1000,string $format='csv'):string {
 $q=$pdo->prepare('SELECT id FROM bank_accounts WHERE id=?');$q->execute([$account]);if(!$q->fetchColumn())throw new RuntimeException('Bankkonto unbekannt.');$rows=bankParseStatement($raw,$map,$locale,$delimiter,$limit,$format);$ibanHash=$format==='camt'?hash('sha256',bankIban((string)($map['expected_iban']??''))):null;if($ibanHash){bankAssertIbanBinding($pdo,'bank_accounts',$account,$ibanHash);$q=$pdo->prepare('SELECT import_iban_hash FROM bank_accounts WHERE id=?');$q->execute([$account]);$bound=$q->fetchColumn();if($bound&&!hash_equals($bound,$ibanHash))throw new RuntimeException('CAMT-Kontoidentität passt nicht zur bisherigen Kontobindung.');}$checkPossible=$format==='camt';if(!$checkPossible&&(int)$pdo->query("SELECT COUNT(*) FROM app_migrations WHERE version='350_final'")->fetchColumn()){$binding=$pdo->prepare('SELECT import_iban_hash FROM bank_accounts WHERE id=?');$binding->execute([$account]);$checkPossible=(bool)$binding->fetchColumn();}$possible=bankPossibleDuplicates($pdo,'bank_transactions',$account,$rows,$checkPossible);$conflicts=[];$duplicates=0;$q=$pdo->prepare('SELECT record_hash FROM bank_transactions WHERE account_id=? AND source_key=?');foreach($rows as $r){$q->execute([$account,$r['source_key']]);$old=$q->fetchColumn();if($old&&$old!==$r['record_hash'])$conflicts[]=$r['external_id'];elseif($old)$duplicates++;}$token=bin2hex(random_bytes(32));$pdo->prepare('INSERT INTO bank_imports(token,account_id,admin_id,file_hash,payload) VALUES(?,?,?,?,?)')->execute([$token,$account,$admin,hash('sha256',$raw),json_encode(['rows'=>$rows,'conflicts'=>$conflicts,'duplicates'=>$duplicates,'iban_hash'=>$ibanHash,'check_possible'=>$checkPossible,'possible_duplicates'=>$possible],JSON_THROW_ON_ERROR)]);return $token;
}
function bankApply(PDO $pdo,int $admin,string $token,bool $possibleReviewed=false):void {
 $pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM bank_imports WHERE token=? AND admin_id=? FOR UPDATE');$q->execute([$token,$admin]);$p=$q->fetch();if(!$p)throw new RuntimeException('Import fehlt.');if($p['applied_at']){$pdo->commit();return;}if(strtotime($p['created_at'].' UTC')<time()-7200)throw new RuntimeException('Vorschau abgelaufen.');$payload=json_decode($p['payload'],true,512,JSON_THROW_ON_ERROR);if($payload['conflicts'])throw new RuntimeException('Quellen-ID-Konflikte: keine Übernahme, keine stillen Umsatzänderungen.');if(!empty($payload['iban_hash']))bankAssertIbanBinding($pdo,'bank_accounts',(int)$p['account_id'],$payload['iban_hash'],true);$q=$pdo->prepare('SELECT * FROM bank_accounts WHERE id=? FOR UPDATE');$q->execute([$p['account_id']]);$accountRow=$q->fetch();if(!$accountRow)throw new RuntimeException('Konto fehlt.');bankReviewPossible($payload['possible_duplicates']??[],bankPossibleDuplicates($pdo,'bank_transactions',(int)$p['account_id'],$payload['rows'],!empty($payload['check_possible'])||!empty($accountRow['import_iban_hash'])),$possibleReviewed);if(!empty($payload['iban_hash'])){if(!empty($accountRow['import_iban_hash'])&&!hash_equals($accountRow['import_iban_hash'],$payload['iban_hash']))throw new RuntimeException('CAMT-Kontoidentität inzwischen geändert.');$pdo->prepare('UPDATE bank_accounts SET import_iban_hash=? WHERE id=?')->execute([$payload['iban_hash'],$p['account_id']]);}$count=0;foreach($payload['rows'] as $r){$q=$pdo->prepare('SELECT record_hash FROM bank_transactions WHERE account_id=? AND source_key=?');$q->execute([$p['account_id'],$r['source_key']]);$old=$q->fetchColumn();if($old){if($old!==$r['record_hash'])throw new RuntimeException('Umsatz seit Vorschau abweichend.');continue;}$pdo->prepare('INSERT INTO bank_transactions(account_id,source_key,record_hash,external_id,booked_on,value_on,amount_cents,currency,purpose,counterparty) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$p['account_id'],$r['source_key'],$r['record_hash'],$r['external_id'],$r['booked_on'],$r['value_on'],$r['amount_cents'],$r['currency'],$r['purpose'],$r['counterparty']]);$count++;}$pdo->prepare('UPDATE bank_imports SET applied_at=UTC_TIMESTAMP() WHERE token=?')->execute([$token]);gszAudit($pdo,$admin,'bank_import',['account_id'=>(int)$p['account_id'],'count'=>$count,'file_hash'=>$p['file_hash'],'similarity_reviewed'=>$possibleReviewed]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
}
function financeMatch(array $transaction,array $candidates):array {
 $out=[];foreach($candidates as $c){$remaining=(int)$c['remaining_cents'];if($remaining===0||($remaining>0)!==((int)$transaction['amount_cents']>0))continue;$score=abs($remaining)===abs((int)$transaction['amount_cents'])?60:20;$reasons=[$score===60?'Betrag stimmt überein':'Nur Vorzeichen passend, Teilzahlung prüfen'];$days=abs((new DateTimeImmutable($transaction['booked_on']))->diff(new DateTimeImmutable($c['date']))->days);if($days<=7){$score+=20;$reasons[]='Datum innerhalb 7 Tagen';}$name=mb_strtolower(trim($c['name']));if(mb_strlen($name)>=3&&str_contains(mb_strtolower($transaction['counterparty'].' '.$transaction['purpose']),$name)){$score+=20;$reasons[]='Name im Umsatztext';}$out[]=$c+['score'=>$score,'reasons'=>$reasons];}usort($out,fn($a,$b)=>[$b['score'],$a['kind'],$a['id']]<=>[$a['score'],$b['kind'],$b['id']]);return array_slice($out,0,10);
}
